const root=document.querySelector('#indiretos-view');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=['Todos','Escritório','Limpeza','Cozinha','EPIs','Uniformes'];
let rows=[],history=[],category='Todos',tab='MRP',search='',selectedCode='';
const routeTabs={'insumos-mrp':'MRP','insumos-estoque':'Estoque','insumos-prazos':'Prazos','insumos-importacoes':'Importações',indiretos:'MRP'};
function syncIndirectNav(){const key=location.hash.slice(1),active=Object.hasOwn(routeTabs,key),children=document.querySelector('#nav-indirect-children'),parent=document.querySelector('#nav-indirect-toggle');if(!children||!parent)return;const open=active&&parent.dataset.collapsed!=='true';children.hidden=!open;parent.setAttribute('aria-expanded',String(open));parent.classList.toggle('indirect-active',open);document.querySelectorAll('[data-indirect-tab]').forEach(a=>{if(a.dataset.indirectTab===routeTabs[key])a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(active)tab=routeTabs[key];}

const num=s=>{let t=String(s??'').trim().replace(/\s/g,'');if(t.includes(','))t=t.replace(/\./g,'').replace(',','.');return Number(t)||0};
const iso=s=>{const m=String(s||'').match(/^(\d{2})\/(\d{2})\/(\d{4})/);return m?m[3]+'-'+m[2]+'-'+m[1]:''};
const br=s=>s?s.slice(8,10)+'/'+s.slice(5,7)+'/'+s.slice(0,4):'—';
function classify(name,group){let s=name.toUpperCase();if(group==='epis')return /CAMISETA|CALCA|CALÇA|UNIFORME|JALECO/.test(s)?'Uniformes':'EPIs';if(/PAPEL TOALHA|VASSOUR|ESPONJA|DETERGENTE|DESINFET|SABAO|SABÃO|LIMPEZA|ESCOVA|AROMATIZ/.test(s))return 'Limpeza';if(/COPO|CAFÉ|CAFE|FILTRO DE PAPEL|GUARDANAPO|COZINHA/.test(s))return 'Cozinha';return 'Escritório'}
function parseCSV(text,group){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(s=>s.trim());const split=line=>{let out=[],v='',q=false;for(let i=0;i<line.length;i++){let c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){v+='"';i++}else q=!q}else if(c===';'&&!q){out.push(v.trim());v=''}else v+=c}out.push(v.trim());return out};const headers=split(lines.shift()).map(s=>s.toLowerCase().replace(/\s+/g,' ').trim());const get=(cols,name)=>cols[headers.indexOf(name)]||'';if(!headers.includes('cód. item')||!headers.includes('dt. entrega')||!headers.includes('quantidade'))throw Error('CSV incompatível: verifique as colunas Cód. Item, Dt. Entrega e Quantidade.');return lines.map(line=>{const c=split(line),code=get(c,'cód. item'),order=get(c,'ordem'),delivery=iso(get(c,'dt. entrega')),description=get(c,'descrição');return {id:[order,code,delivery].join('|'),code,order,description,quantity:num(get(c,'quantidade')),unit:get(c,'um'),purchase:iso(get(c,'dt. compra')),delivery,company:get(c,'emp.'),type:get(c,'tipo'),category:classify(description,group),status:'Pendente',stock:null,safety:null,consumption:null,lead:null}}).filter(x=>x.code)}
async function load(){try{const r=await fetch('/api/indirect-materials',{cache:'no-store'});if(r.status===401){root.innerHTML='<section class="panel"><h3>Materiais Indiretos</h3><p>Sua sessão expirou. Faça login novamente para carregar as importações.</p><p><a href="/login" class="btn">Entrar novamente</a></p></section>';return}const type=r.headers.get('content-type')||'';if(!type.includes('application/json'))throw Error('O servidor retornou uma página em vez dos dados. Atualize a tela e tente novamente.');const j=await r.json();if(!r.ok)throw Error(j.error||'Não foi possível carregar os materiais.');rows=Array.isArray(j.items)?j.items:[];history=Array.isArray(j.history)?j.history:[];render()}catch(e){root.innerHTML='<section class="panel"><h3>Materiais Indiretos</h3><p>'+esc(e.message)+'</p><button type="button" id="indirect-retry-load">Tentar novamente</button></section>';root.querySelector('#indirect-retry-load')?.addEventListener('click',load)}}
async function save(){const r=await fetch('/api/indirect-materials',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:rows,history})});const j=await r.json();if(!r.ok)throw Error(j.error||'Falha ao salvar.')}
const today=()=>new Date().toLocaleDateString('en-CA');
function filtered(){return rows.filter(x=>(category==='Todos'||x.category===category)&&(!search||[x.code,x.description,x.order].join(' ').toLowerCase().includes(search.toLowerCase())))}
function status(x){return x.status==='Recebido'?'Recebido':x.status==='Cancelado'?'Cancelado':x.delivery&&x.delivery<today()?'Atrasado':x.status||'Pendente'}

function deadlineView(){
 // Relatórios CSV do ERP indicam necessidades, não compras confirmadas.
 const purchases=rows.filter(x=>x.source==='manual-purchase');
 const statuses=['Aguardando entrega','Parcial','Entregue','Cancelado','Atrasado'];
 const state=x=>x.status==='Recebido'?'Entregue':x.status==='Cancelado'?'Cancelado':num(x.delivered)>0?'Parcial':status(x)==='Atrasado'?'Atrasado':'Aguardando entrega';
 const now=today(),week=new Date(now+'T12:00:00'),next=new Date(week);next.setDate(next.getDate()+7);const horizon=next.toISOString().slice(0,10);
 const count=k=>purchases.filter(x=>state(x)===k).length;
 const suppliers=[...new Set(purchases.map(x=>x.supplier||'').filter(Boolean))].sort();
 const options=items=>items.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('');
 const sel=(attr,values,all='Todos')=>'<select '+attr+'><option value="">'+all+'</option>'+options(values)+'</select>';
 const start=root.dataset.from||'',end=root.dataset.to||'',supplier=root.dataset.indSupplier||'',st=root.dataset.indStatus||'',q=root.dataset.indQuery||'';
 const matches=x=>(!supplier||String(x.supplier||'').toLowerCase().includes(supplier.toLowerCase()))&&(!st||state(x)===st)&&(!q||[x.code,x.description,x.order].join(' ').toLowerCase().includes(q.toLowerCase()))&&(!start||x.delivery>=start)&&(!end||x.delivery<=end);
 const shown=purchases.filter(matches).sort((a,b)=>a.delivery.localeCompare(b.delivery));
 const rowsHtml=shown.map(x=>{const stx=state(x),left=Math.max(0,x.quantity-num(x.delivered));return '<tr class="'+(stx==='Atrasado'?'ind-late':stx==='Entregue'?'ind-done':'')+'"><td>'+esc(x.code)+'</td><td>'+esc(x.description)+'</td><td>'+esc(x.order)+'</td><td>'+esc(x.contact||'—')+'</td><td>'+esc(x.supplier||'—')+'</td><td>'+stx+'</td><td>'+br(x.delivery)+'</td><td>'+x.quantity+'</td><td>'+num(x.delivered)+'</td><td>'+left+'</td><td>'+esc(x.unit)+'</td><td class="ind-actions"><button data-partial="'+esc(x.id)+'" title="Entrega parcial">½</button><button data-receive="'+esc(x.id)+'" title="Receber tudo">✓</button><button data-cancel="'+esc(x.id)+'" title="Cancelar pedido">×</button></td></tr>'}).join('');
 return '<div class="deadline-kpis">'+[['Atrasados',count('Atrasado')],['Próxima semana',purchases.filter(x=>!['Recebido','Cancelado'].includes(x.status)&&x.delivery>=now&&x.delivery<=horizon).length],['Pendentes',purchases.filter(x=>!['Recebido','Cancelado'].includes(x.status)).length],['Parciais',count('Parcial')],['Entregues',count('Entregue')]].map(([label,value])=>'<div><strong>'+value+'</strong><span>'+label+'</span></div>').join('')+'</div>'+
 '<section class="panel deadline-purchase-entry"><details><summary>+ Adicionar pedido comprado</summary><div class="deadline-pdf-import"><strong>Importar pedido do FoccoERP</strong><input type="file" id="ind-purchase-pdf" accept="application/pdf,.pdf"><button type="button" id="ind-import-purchase-pdf">Importar PDF</button><span id="ind-purchase-pdf-status" role="status"></span></div><form id="ind-purchase-form"><div class="ind-order-fields"><label>Pedido de compra<input name="order" required></label><label>Código do item<input name="code" required></label><label>Descrição<input name="description" required></label><label>Quantidade<input name="quantity" type="number" min="0.001" step="any" required></label><label>UN<input name="unit" value="UN" required></label><label>Fornecedor<input name="supplier"></label><label>Contato<input name="contact"></label><label>Entrega prevista<input name="delivery" type="date" required></label></div><button type="submit">Salvar pedido comprado</button></form></details></section>'+
 '<section class="panel deadline-report"><h3>📊 Relatório <small>Filtre antes de imprimir ou baixar</small></h3><div class="deadline-report-filters"><label>Empresa'+sel('data-ind-report-company',['Colafix'])+'</label><label>Fornecedor'+sel('data-ind-report-supplier',suppliers)+'</label><label>Status'+sel('data-ind-report-status',statuses)+'</label><label>Data inicial<input type="date" data-from value="'+start+'"></label><label>Data final<input type="date" data-to value="'+end+'"></label></div><div class="deadline-report-footer"><span>'+shown.length+' registros</span><div><button type="button" data-ind-print>🖨 Imprimir relatório</button><button type="button" data-ind-excel>📊 Baixar Excel</button></div></div></section>'+
 '<section class="panel"><h3>Controle dos prazos</h3><p class="hint">Branco: prazo normal · Vermelho: atrasado · Verde: entregue. Entrega parcial continua pendente até o saldo ser recebido.</p><div class="cement-filters"><label>Fornecedor<input data-ind-supplier placeholder="Todos" value="'+esc(supplier)+'"></label><label>Status'+sel('data-ind-status',statuses)+'</label><label>Buscar<input data-ind-query placeholder="Código, produto ou pedido" value="'+esc(q)+'"></label></div><div class="table-scroll"><table class="deadlines-grid"><thead><tr>'+['Cód','Produto','Pedido','Contato','Fornecedor','Status','Entrega prevista','Pedido','Entregue','Saldo','UN','Ações'].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+(rowsHtml||'<tr><td colspan="12">Nenhum pedido comprado cadastrado. As necessidades importadas do ERP não são entregas.</td></tr>')+'</tbody></table></div></section>';
}
function wireDeadlines(){
 const st=x=>x.status==='Recebido'?'Entregue':x.status==='Cancelado'?'Cancelado':num(x.delivered)>0?'Parcial':status(x)==='Atrasado'?'Atrasado':'Aguardando entrega';
 for(const [attr,key] of [['data-ind-supplier','indSupplier'],['data-ind-status','indStatus'],['data-ind-query','indQuery'],['data-from','from'],['data-to','to']]){const el=root.querySelector('['+attr+']');if(el){el.value=root.dataset[key]||'';el.onchange=()=>{root.dataset[key]=el.value;render()}}}
 for(const [attr,key] of [['data-ind-report-supplier','indSupplier'],['data-ind-report-status','indStatus']]){const el=root.querySelector('['+attr+']');if(el){el.value=root.dataset[key]||'';el.onchange=()=>{root.dataset[key]=el.value;render()}}}
 const importButton=root.querySelector('#ind-import-purchase-pdf');
 if(importButton)importButton.onclick=async()=>{
  const file=root.querySelector('#ind-purchase-pdf')?.files?.[0],message=root.querySelector('#ind-purchase-pdf-status'),form=root.querySelector('#ind-purchase-form');
  if(!file){message.textContent='Selecione o PDF do pedido.';return}
  importButton.disabled=true;message.textContent='Lendo PDF do FoccoERP…';
  try{
   const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(Error('Falha ao ler o arquivo.'));reader.readAsDataURL(file)});
   const response=await fetch('/api/deadlines/import-pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file:{name:file.name,content}})});
   const data=await response.json();if(!response.ok)throw Error(data.error||'Não foi possível extrair o pedido.');
   const items=data.items||[];if(!items.length)throw Error('Nenhum item encontrado no PDF.');
   form.elements.order.value=data.purchaseOrder||'';
   form.elements.supplier.value=data.supplier||'';
   form.elements.contact.value=data.contact||'';
   const first=items[0];form.elements.code.value=first.code||'';form.elements.description.value=first.product||first.description||'';
   form.elements.quantity.value=first.quantity||'';form.elements.unit.value=first.unit||'UN';
   form.elements.delivery.value=first.deliveryDate||first.itemDeliveryDate||data.deliveryDate||'';
   form.dataset.importedItems=JSON.stringify(items);
   message.textContent=items.length+' item(ns) extraído(s). Confira os campos antes de salvar. '+(items.length>1?'Ao salvar, todos os itens do PDF serão cadastrados.':'');
  }catch(error){message.textContent='Erro: '+error.message}finally{importButton.disabled=false}
 };
 const form=root.querySelector('#ind-purchase-form');if(form)form.onsubmit=async e=>{e.preventDefault();const d=new FormData(form),code=String(d.get('code')).trim(),order=String(d.get('order')).trim(),delivery=String(d.get('delivery'));const imported=JSON.parse(form.dataset.importedItems||'[]');
 const items=imported.length?imported.map((item,i)=>({code:i===0?code:String(item.code||'').trim(),description:i===0?String(d.get('description')):String(item.product||item.description||''),quantity:i===0?num(d.get('quantity')):num(item.quantity),unit:i===0?String(d.get('unit')):String(item.unit||'UN'),delivery:i===0?delivery:String(item.deliveryDate||item.itemDeliveryDate||delivery)})):[{code,description:String(d.get('description')),quantity:num(d.get('quantity')),unit:String(d.get('unit')),delivery}];
 const additions=items.filter(item=>item.code&&item.quantity>0).map(item=>({...item,id:[order,item.code,item.delivery].join('|'),order,supplier:String(d.get('supplier')),contact:String(d.get('contact')),status:'Pendente',source:'manual-purchase',category:classify(item.description,'other'),stock:null,safety:null,consumption:null,lead:null,delivered:0}));
 if(!additions.length){alert('Nenhum item válido para salvar.');return}
 if(additions.some(x=>rows.some(y=>y.id===x.id))){alert('Um dos itens deste pedido já está cadastrado.');return}
 rows.push(...additions);try{await save();render()}catch(err){rows.splice(-additions.length,additions.length);alert(err.message)}};
 for(const [attr,action] of [['data-receive','receive'],['data-cancel','cancel'],['data-partial','partial']])root.querySelectorAll('['+attr+']').forEach(btn=>btn.onclick=async()=>{const x=rows.find(x=>x.id===btn.getAttribute(attr));if(!x)return;const old={status:x.status,delivered:x.delivered};if(action==='receive'){x.delivered=x.quantity;x.status='Recebido'}else if(action==='cancel'){if(!confirm('Cancelar este pedido?'))return;x.status='Cancelado'}else{const value=prompt('Quantidade total já entregue (até '+x.quantity+'):',String(num(x.delivered)));if(value===null)return;const amount=num(value);if(amount<0||amount>x.quantity){alert('Quantidade inválida.');return}x.delivered=amount;x.status=amount>=x.quantity?'Recebido':'Pendente'}try{await save();render()}catch(e){Object.assign(x,old);alert(e.message)}});
 const report=()=>rows.filter(x=>x.source==='manual-purchase').filter(x=>(!root.dataset.indSupplier||String(x.supplier||'').toLowerCase().includes(root.dataset.indSupplier.toLowerCase()))&&(!root.dataset.indStatus||st(x)===root.dataset.indStatus)&&(!root.dataset.from||x.delivery>=root.dataset.from)&&(!root.dataset.to||x.delivery<=root.dataset.to));
 const excel=root.querySelector('[data-ind-excel]');if(excel)excel.onclick=()=>{const data=[['Código','Produto','Pedido','Fornecedor','Contato','Status','Entrega','Quantidade','Entregue','Saldo','UN'],...report().map(x=>[x.code,x.description,x.order,x.supplier||'',x.contact||'',st(x),br(x.delivery),x.quantity,num(x.delivered),Math.max(0,x.quantity-num(x.delivered)),x.unit])];const csv='\uFEFF'+data.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='prazos-insumos-epis.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
 const print=root.querySelector('[data-ind-print]');if(print)print.onclick=()=>{const html='<h2>Relatório de prazos - Insumos e EPIs</h2><table border="1" cellspacing="0" cellpadding="6"><tr><th>Código</th><th>Produto</th><th>Pedido</th><th>Fornecedor</th><th>Entrega</th><th>Status</th></tr>'+report().map(x=>'<tr>'+[x.code,x.description,x.order,x.supplier||'',br(x.delivery),st(x)].map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</table>';const w=window.open('','_blank');if(!w){alert('Permita pop-ups para imprimir.');return}w.document.write('<!doctype html><html><head><title>Relatório</title></head><body>'+html+'</body></html>');w.document.close();w.print()};
}


function indirectPendingPanel(code,unit){
 const sameUnit=v=>!unit||String(v||'').trim().toUpperCase()===String(unit||'').trim().toUpperCase();
 const pending=rows.filter(x=>x.source==='manual-purchase'&&String(x.code||'').trim().toUpperCase()===String(code||'').trim().toUpperCase()&&!['Recebido','Cancelado','Entregue'].includes(x.status)&&sameUnit(x.unit)).map(x=>({...x,remaining:Math.max(0,num(x.quantity)-num(x.delivered))})).filter(x=>x.remaining>0);
 return '<section class="panel item-pending-panel"><h3>Entregas pendentes · '+esc(code)+'</h3>'+(pending.length?'<p class="hint">Pedidos comprados com saldo pendente na aba Insumos/EPIs · Prazo de entrega.</p>'+table(['Pedido','Fornecedor','Saldo pendente','Previsão','Situação'],pending.map(x=>'<tr><td>'+esc(x.order||'—')+'</td><td>'+esc(x.supplier||'—')+'</td><td>'+esc(x.remaining)+' '+esc(x.unit||'')+'</td><td>'+br(x.delivery)+'</td><td>'+(num(x.delivered)>0?'Parcial':'Pendente')+'</td></tr>')):'<p class="hint">Nenhuma entrega pendente cadastrada para este material.</p>')+'</section>';
}

function render(){if(!root)return;syncIndirectNav();const f=filtered(),late=rows.filter(x=>status(x)==='Atrasado').length,upcoming=rows.filter(x=>x.status!=='Recebido'&&x.delivery>=today()).length;
const mrpSuppliers=[...new Set(rows.map(x=>x.supplier).filter(Boolean))].sort();
const mrpQuery=root.dataset.mrpQuery||'',mrpSupplier=root.dataset.mrpSupplier||'',mrpDisplay=root.dataset.mrpDisplay||'all';
const mrpCandidates=tab==='MRP'?f.filter(x=>(!mrpSupplier||x.supplier===mrpSupplier)&&(!mrpQuery||[x.code,x.description,x.order].join(' ').toLowerCase().includes(mrpQuery.toLowerCase()))&&(mrpDisplay==='all'||(mrpDisplay==='review'&&(x.stock==null||x.safety==null))||(mrpDisplay==='late'&&status(x)==='Atrasado')||(mrpDisplay==='pending'&&x.status!=='Recebido'&&x.status!=='Cancelado'))):f;
const materialMap=new Map();for(const x of (tab==='Estoque'?rows:mrpCandidates)){if(!x.code)continue;const old=materialMap.get(x.code)||{};const combined={...old,...x};for(const key of ['stock','safety','consumption','lead','initial','minLot','previousStock'])if((x[key]===null||x[key]===undefined||x[key]==='')&&old[key]!==null&&old[key]!==undefined)combined[key]=old[key];materialMap.set(x.code,combined)}const items=[...materialMap.values()];if(!items.some(x=>x.code===selectedCode))selectedCode=items[0]?.code||'';
const chosen=rows.filter(x=>String(x.code).trim()===String(selectedCode).trim()),item=chosen[0],stockStatus=x=>x.stock==null||x.safety==null?'Revisar dados':x.consumption==null||x.consumption===0?'Sem consumo':x.stock<x.safety?'Crítico':x.lead!=null&&x.stock<x.safety+x.consumption/30*x.lead?'Atenção':'Ok';
const stockSuppliers=[...new Set(rows.map(x=>x.supplier).filter(Boolean))].sort();
const stockSupplier=root.dataset.stockSupplier||'',stockRupture=root.dataset.stockRupture||'',stockVariation=root.dataset.stockVariation||'';
const rupture=x=>x.stock==null?'Sem dados':Number(x.stock)<=0?'Ruptura':x.safety==null?'Sem dados':Number(x.stock)<Number(x.safety)?'Risco de ruptura':'Sem ruptura';
const stockItems=items.filter(x=>(!search||[x.code,x.description,x.order].join(' ').toLowerCase().includes(search.trim().toLowerCase()))&&(!root.dataset.stockStatus||stockStatus(x)===root.dataset.stockStatus)&&(!stockSupplier||x.supplier===stockSupplier)&&(!stockRupture||rupture(x)===stockRupture)&&(!stockVariation||(stockVariation==='unknown'&&(x.previousStock==null||x.stock==null))||(stockVariation==='up'&&x.previousStock!=null&&x.stock>x.previousStock)||(stockVariation==='down'&&x.previousStock!=null&&x.stock<x.previousStock)||(stockVariation==='same'&&x.previousStock!=null&&x.stock===x.previousStock)));
const stockZero=items.filter(x=>x.stock!=null&&Number(x.stock)<=0).length,stockLow=items.filter(x=>x.stock!=null&&x.safety!=null&&Number(x.stock)>0&&Number(x.stock)<Number(x.safety)).length;
const mrpAnalysis=()=>{if(!item)return '';const known=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v));const fmtN=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n);const stock=known(item.stock)?Number(item.stock):null,safety=known(item.safety)?Number(item.safety):null,monthly=known(item.consumption)?Number(item.consumption):null,lead=known(item.lead)?Number(item.lead):null;const pending=chosen.filter(x=>x.status!=='Recebido'&&x.status!=='Cancelado').reduce((a,x)=>a+(Number(x.quantity)||0),0);const daily=monthly!=null&&monthly>0?monthly/30:null;const coverage=stock!=null&&daily!=null?stock/daily:null;const reorder=safety!=null&&daily!=null&&lead!=null?safety+daily*lead:null;const projected=stock!=null&&daily!=null&&lead!=null?stock-daily*lead:null;const missing=[stock==null?'saldo físico':null,safety==null?'estoque de segurança':null,monthly==null?'consumo médio mensal':null,lead==null?'tempo de reposição':null].filter(Boolean);const urgent=stock!=null&&safety!=null&&stock<safety;const needs=stock!=null&&reorder!=null&&stock<=reorder;const state=missing.length?'Dados insuficientes':urgent?'Compra urgente':needs?'Atenção: avaliar compra':'Estoque adequado';const fact=(label,value)=>'<div class="ind-mrp-fact"><small>'+label+'</small><strong>'+esc(value)+'</strong></div>';return '<section class="panel ind-mrp-analysis"><h3>Monitoramento e avisos de compra</h3><div class="ind-mrp-alert '+(urgent?'critical':needs?'warning':'')+'"><strong>'+esc(state)+'</strong><p>'+(missing.length?'Para uma análise completa, informe: '+esc(missing.join(', '))+'.':urgent?'O saldo físico está abaixo do estoque de segurança. Priorize a reposição.':needs?'O saldo está no ponto de pedido ou abaixo dele. Verifique a necessidade de compra.':'O saldo está acima do ponto de pedido calculado.')+'</p></div><div class="ind-mrp-facts">'+fact('Saldo físico',stock==null?'Não informado':fmtN(stock)+' '+item.unit)+fact('Estoque de segurança',safety==null?'Não informado':fmtN(safety)+' '+item.unit)+fact('Consumo mensal',monthly==null?'Não informado':fmtN(monthly)+' '+item.unit)+fact('Cobertura estimada',coverage==null?'Não calculável':fmtN(coverage)+' dias')+fact('Ponto de pedido',reorder==null?'Não calculável':fmtN(reorder)+' '+item.unit)+fact('Saldo após reposição',projected==null?'Não calculável':fmtN(projected)+' '+item.unit)+fact('Pedidos pendentes',fmtN(pending)+' '+item.unit)+fact('Prazo de reposição',lead==null?'Não informado':fmtN(lead)+' dias')+'</div><details class="ind-mrp-explain"><summary>Como são calculados os avisos</summary><p>Consumo diário = consumo mensal / 30. Ponto de pedido = estoque de segurança + consumo diário × prazo de reposição. Saldo projetado = saldo físico − consumo diário × prazo. A cobertura é estimada sem descontar pedidos futuros. Pedidos pendentes são exibidos separadamente e não são considerados estoque disponível até o recebimento.</p><p>Este painel usa os parâmetros cadastrados em Insumos/EPIs. Não gera quantidade de compra nem data de emissão quando faltam dados confiáveis do ERP.</p></details></section>'};
const mrpPlan=()=>{if(!item)return '';const ok=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v));const stock=ok(item.stock)?Number(item.stock):null,safety=ok(item.safety)?Number(item.safety):null,cons=ok(item.consumption)?Number(item.consumption):null,lead=ok(item.lead)?Number(item.lead):null;const daily=cons>0?cons/30:null,point=daily!=null&&safety!=null&&lead!=null?safety+daily*lead:null;const fmt=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n);const rowsERP=chosen.filter(x=>x.order||x.purchase||x.delivery);const missing=[stock==null?'saldo físico':null,safety==null?'estoque de segurança':null,cons==null?'consumo mensal':null,lead==null?'prazo de reposição':null].filter(Boolean);const action=missing.length?'Dados insuficientes':daily==null?'Consumo não informado':stock<=point?'Avaliar compra':'Estoque adequado';const pending=chosen.filter(x=>!['Recebido','Cancelado'].includes(x.status)).reduce((a,x)=>a+(Number(x.quantity)||0),0);const f=(label,value)=>'<div class="ind-mrp-fact"><small>'+label+'</small><strong>'+esc(value)+'</strong></div>';return '<div class="ind-mrp-plan"><details class="panel ind-mrp-origin"><summary>Origem e regra de compra</summary><div class="ind-mrp-plan-content"><p>Dados dos arquivos importados do FoccoERP e parâmetros cadastrados do material. As necessidades listadas são registros de origem, não pedidos criados pelo sistema.</p><p>Ponto de pedido = estoque de segurança + (consumo mensal / 30) × prazo de reposição. A recomendação é bloqueada quando faltam dados.</p></div></details><section class="panel"><h3>Plano de ação</h3><div class="ind-mrp-plan-content"><strong>'+esc(action)+'</strong><p>'+(missing.length?'Preencha: '+esc(missing.join(', '))+'.':daily==null?'Sem consumo positivo para estimar compra.':stock<=point?'Saldo no ponto de pedido ou abaixo. Verifique os pedidos existentes antes de comprar.':'Saldo acima do ponto de pedido.')+'</p><div class="ind-mrp-facts">'+f('Data da análise',new Date().toLocaleDateString('pt-BR'))+f('Quantidade indicativa',point!=null&&stock!=null&&daily!=null?fmt(Math.max(0,Math.ceil(point-stock)))+' '+item.unit:'Não calculável')+f('Ponto de pedido',point==null?'Não calculável':fmt(point)+' '+item.unit)+f('Pedidos pendentes',fmt(pending)+' '+item.unit)+'</div><details class="ind-mrp-explain"><summary>Ver como foi calculado</summary><p>Consumo diário: '+(daily==null?'Não calculável':fmt(daily)+' '+esc(item.unit)+'/dia')+'. Estoque de segurança: '+(safety==null?'Não informado':fmt(safety))+'. Prazo de reposição: '+(lead==null?'Não informado':fmt(lead)+' dias')+'.</p><p>A quantidade é indicativa, não considera lotes, pedidos futuros ou datas de entrega e não representa uma ordem de compra aprovada.</p></details></div></section><section class="panel"><h3>Necessidades informadas pelo ERP</h3><div class="ind-mrp-plan-content">'+table(['Ordem','Tipo','Data de compra','Entrega','Quantidade'],rowsERP.map(x=>'<tr><td>'+esc(x.order||'—')+'</td><td>'+esc(x.type||'—')+'</td><td>'+br(x.purchase)+'</td><td>'+br(x.delivery)+'</td><td>'+fmt(Number(x.quantity)||0)+' '+esc(x.unit)+'</td></tr>'))+'<p>Quantidades dos registros importados, não sugestões calculadas.</p></div></section></div>'};
const profile=()=>item?'<div class="ind-detail-title"><h2>'+esc(item.description)+'</h2><small>'+esc(item.code)+' · '+esc(item.unit)+'</small></div><div class="ind-detail-grid"><section class="panel"><h3>Perfil do item</h3>'+table(['Tipo','Referência','Data compra','Data entrega','Quantidade'],chosen.map(x=>'<tr><td>'+esc(x.type||'OCP')+'</td><td>'+esc(x.order)+'</td><td>'+br(x.purchase)+'</td><td>'+br(x.delivery)+'</td><td>'+esc(x.quantity)+' '+esc(x.unit)+'</td></tr>'))+'</section><section class="panel"><h3>Parâmetros de reposição</h3><div class="ind-params">'+[['stock','Saldo físico'],['safety','Estoque segurança'],['consumption','Consumo médio mensal'],['lead','Tempo de reposição (dias)']].map(([k,label])=>'<label>'+label+'<input type="number" min="0" step="any" data-value-id="'+esc(item.id)+'" data-field="'+k+'" value="'+(item[k]??'')+'" placeholder="Não informado"></label>').join('')+'</div></section><section class="panel"><h3>Análise de compra</h3><div class="ind-metric">'+esc(stockStatus(item))+'</div><p>'+(item.stock==null||item.safety==null?'Informe saldo físico e estoque de segurança para analisar a necessidade.':item.stock<item.safety?'Saldo abaixo do estoque de segurança. Verifique a reposição.':'Saldo acima do estoque de segurança.')+'</p><small>Pedidos pendentes: '+chosen.filter(x=>x.status!=='Recebido'&&x.status!=='Cancelado').reduce((a,x)=>a+x.quantity,0)+' '+esc(item.unit)+'</small></section></div>':'<p class="empty-state">Importe os arquivos CSV para iniciar a análise.</p>';
root.innerHTML=`
${tab==='MRP'?'<div class="ind-mrp-filters"><label>Fornecedor preferencial<select data-mrp-supplier><option value="">Todos os fornecedores</option>'+mrpSuppliers.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('')+'</select></label><label>Exibir<select data-mrp-display><option value="all">Todos os itens do relatório</option><option value="review">Revisar dados</option><option value="late">Pedidos atrasados</option><option value="pending">Pedidos pendentes</option></select></label><label>Material selecionado<input data-mrp-query type="search" placeholder="Código ou nome do material" value="'+esc(mrpQuery)+'"></label><button type="button" data-mrp-clear>Limpar material</button><span class="ind-mrp-count">'+items.length+' de '+new Set(f.map(x=>x.code)).size+' itens</span></div><div class="section-title"><h2>Itens do relatório MRP</h2><span>Selecione um material para analisar</span></div><div class="material-grid ind-material-grid">'+items.map(x=>'<button class="material '+(selectedCode===x.code?'active':'')+'" data-select-code="'+esc(x.code)+'"><span><small>'+esc(x.code)+' · '+esc(x.unit)+'</small><strong>'+esc(x.description)+'</strong></span><span class="material-tag">'+esc(stockStatus(x))+'</span></button>').join('')+'</div>'+profile()+mrpAnalysis()+mrpPlan()+indirectPendingPanel(selectedCode,item?.unit):tab==='Estoque'?'<div class="ind-stock-toolbar"><label>Buscar produto<input data-stock-search placeholder="Código ou nome do material" value="'+esc(search)+'"></label><label>Fornecedor preferencial<select data-stock-supplier><option value="">Todos os fornecedores</option>'+stockSuppliers.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('')+'</select></label><label>Status de cobertura<select data-stock-status><option value="">Todos</option><option>Ok</option><option>Atenção</option><option>Crítico</option><option>Sem consumo</option><option>Revisar dados</option></select></label><label>Variação de estoque<select data-stock-variation><option value="">Todas</option><option value="up">Aumentou</option><option value="down">Diminuiu</option><option value="same">Sem alteração</option><option value="unknown">Sem histórico</option></select></label><label>Status ruptura<select data-stock-rupture><option value="">Todos</option><option>Sem ruptura</option><option>Risco de ruptura</option><option>Ruptura</option><option>Sem dados</option></select></label></div><div class="ind-stock-summary"><strong>'+items.length+' materiais cadastrados</strong> · <strong>'+stockZero+' zerados</strong> · <strong>'+stockLow+' abaixo do mínimo</strong> <button type="button" data-stock-reset>Limpar filtros e mostrar todos</button></div><div class="ind-stock-layout"><section class="panel"><h3>Posição dos materiais <small>'+stockItems.length+' materiais</small></h3>'+table(['Código / produto','UM','Saldo total','Estoque segurança','Cobertura (dias)','Status'],stockItems.map(x=>'<tr class="'+(selectedCode===x.code?'selected-row':'')+'"><td><button class="row-select" data-select-code="'+esc(x.code)+'"><small>'+esc(x.code)+'</small>'+esc(x.description)+'</button></td><td>'+esc(x.unit)+'</td><td>'+(x.stock??'—')+'</td><td>'+(x.safety??'—')+'</td><td>'+(x.stock!=null&&x.consumption>0?(x.stock/x.consumption*30).toFixed(1):'—')+'</td><td>'+esc(stockStatus(x))+'</td></tr>'))+'</section><aside><section class="panel"><h3>Status de cobertura</h3>'+['Ok','Atenção','Crítico','Sem consumo','Revisar dados'].map(st=>'<div class="status-bar"><span>'+st+'</span><div><i class="'+(st==='Ok'?'ok':st==='Crítico'?'critical':'attention')+'" style="width:'+(items.length?items.filter(x=>stockStatus(x)===st).length/items.length*100:0)+'%"></i></div><strong>'+items.filter(x=>stockStatus(x)===st).length+'</strong></div>').join('')+'</section><section class="panel"><h3>Perfil · '+esc(selectedCode)+'</h3>'+profile()+'</section></aside></div>':tab==='Prazos'?deadlineView():'<section class="panel import-panel"><h3>Atualizar dados do sistema</h3><p>Selecione os relatórios de insumos e EPIs. Confira os arquivos antes de importar. Os dados são mantidos separados das matérias-primas.</p><form id="ind-import-form"><label>Necessidades de compra (CSV)<input id="ind-import-csv" type="file" accept=".csv,text/csv" multiple required></label><label>Perfil dos itens (PDF)<input id="ind-import-profile" type="file" accept=".pdf" multiple></label><label>Saldo dos almoxarifados (PDF)<input id="ind-import-stock" type="file" accept=".pdf" multiple></label><button type="submit" id="ind-import-check">Conferir arquivos</button></form><div id="ind-import-result" role="status" aria-live="polite"></div><button id="ind-import-save" hidden type="button">Salvar lote no histórico</button><p>Os PDFs RPLA0300 e REST0331 são conferidos antes de salvar. Os pedidos não são somados ao saldo físico.</p></section><section class="panel import-panel"><h3>Histórico de lotes importados</h3><div id="ind-import-history">Os lotes serão registrados após a importação.</div></section>'}
<p class="method-note">As quantidades dos pedidos não são saldos físicos. Os indicadores de cobertura só são calculados quando saldo e consumo forem informados.</p><p data-feedback role="status"></p>`;
if(tab==='Prazos')wireDeadlines();
if(tab==='MRP'){
 const supplier=root.querySelector('[data-mrp-supplier]'),display=root.querySelector('[data-mrp-display]'),query=root.querySelector('[data-mrp-query]'),clear=root.querySelector('[data-mrp-clear]');
 supplier.value=mrpSupplier;display.value=mrpDisplay;
 supplier.onchange=()=>{root.dataset.mrpSupplier=supplier.value;render()};
 display.onchange=()=>{root.dataset.mrpDisplay=display.value;render()};
 query.oninput=()=>{const pos=query.selectionStart;root.dataset.mrpQuery=query.value;render();const el=root.querySelector('[data-mrp-query]');el.focus();el.setSelectionRange(pos,pos)};
 clear.onclick=()=>{root.dataset.mrpQuery='';selectedCode='';render()};
}
const resetStock=root.querySelector('[data-stock-reset]');if(resetStock)resetStock.onclick=()=>{search='';category='Todos';for(const key of ['stockStatus','stockSupplier','stockRupture','stockVariation'])delete root.dataset[key];render()};
const stockInput=root.querySelector('[data-stock-search]');if(stockInput)stockInput.oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();const el=root.querySelector('[data-stock-search]');if(el){el.focus();el.setSelectionRange(pos,pos)}};
const stockStatusFilter=root.querySelector('[data-stock-status]');if(stockStatusFilter){stockStatusFilter.value=root.dataset.stockStatus||'';stockStatusFilter.onchange=e=>{root.dataset.stockStatus=e.target.value;render()};}
for(const [selector,key] of [['[data-stock-supplier]','stockSupplier'],['[data-stock-variation]','stockVariation'],['[data-stock-rupture]','stockRupture']]){const el=root.querySelector(selector);if(el){el.value=root.dataset[key]||'';el.onchange=()=>{root.dataset[key]=el.value;render()}}}
root.querySelectorAll('[data-select-code]').forEach(b=>b.onclick=()=>{const code=b.dataset.selectCode;if(!code)return;const scrolls=[...root.querySelectorAll('.table-scroll,.ind-stock-layout')].map(el=>({el,top:el.scrollTop,left:el.scrollLeft}));selectedCode=code;render();const fresh=[...root.querySelectorAll('.table-scroll,.ind-stock-layout')];scrolls.forEach((v,i)=>{if(fresh[i]){fresh[i].scrollTop=v.top;fresh[i].scrollLeft=v.left}})});

const importForm=root.querySelector('#ind-import-form');
if(importForm){const check=root.querySelector('#ind-import-check'),result=root.querySelector('#ind-import-result'),commit=root.querySelector('#ind-import-save');let pending=null;const hist=()=>{const el=root.querySelector('#ind-import-history');el.innerHTML=history.map(x=>'<p>'+esc(x.date)+' · '+esc(x.count)+' necessidades · '+esc(x.files.join(', '))+'</p>').join('')||'Nenhum lote importado nesta sessão.'};hist();importForm.onchange=()=>{pending=null;commit.hidden=true;result.textContent='Arquivos alterados. Confira novamente antes de salvar.'};const readPdf=async(file,kind)=>{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const r=await fetch('/api/indirect-materials/parse-pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind,content:btoa(binary)})});const j=await r.json();if(!r.ok)throw Error(file.name+': '+(j.error||'Falha ao processar PDF'));return j};
importForm.onsubmit=async e=>{e.preventDefault();commit.hidden=true;pending=null;check.disabled=true;result.textContent='Lendo e validando arquivos...';try{
 const files=[...root.querySelector('#ind-import-csv').files],profiles=[...root.querySelector('#ind-import-profile').files],stocks=[...root.querySelector('#ind-import-stock').files];
 if(!files.length)throw Error('Selecione os CSVs de necessidades.');
 if(!profiles.length||!stocks.length)throw Error('Selecione os PDFs de perfil e de saldo para uma importação completa.');
 let batch=[],parsed=[],dates=new Set();
 for(const file of files){const buf=await file.arrayBuffer();let content=new TextDecoder('utf-8').decode(buf);if(content.includes('�'))content=new TextDecoder('windows-1252').decode(buf);batch.push(...parseCSV(content,/epi|uniform/i.test(file.name)?'epis':'other'))}
 for(const file of profiles)parsed.push({file:file.name,...await readPdf(file,'profile')});
 for(const file of stocks)parsed.push({file:file.name,...await readPdf(file,'stock')});
 for(const p of parsed)if(p.date)dates.add(p.date);
 if(dates.size>1)throw Error('Os PDFs possuem datas de relatório diferentes. Selecione relatórios do mesmo dia.');
 const byCode=new Map();
 for(const p of parsed){for(const x of p.items){const old=byCode.get(x.code)||{code:x.code};byCode.set(x.code,{...old,...Object.fromEntries(Object.entries(x).filter(([k,v])=>v!==null&&v!==undefined&&v!==''))})}}
 const updated=batch.map(x=>({...x,...(byCode.get(x.code)||{}),id:x.id,code:x.code,order:x.order,quantity:x.quantity,delivery:x.delivery,description:x.description,category:x.category}));
 const notMatched=[...new Set(batch.map(x=>x.code))].filter(code=>!byCode.has(code));
 pending={batch:updated,profileCodes:new Set(parsed.filter(p=>p.kind==='profile').flatMap(p=>p.items.map(x=>x.code))),details:byCode,files:[...files,...profiles,...stocks].map(x=>x.name),date:[...dates][0]||new Date().toISOString().slice(0,10)};
 result.textContent=batch.length+' pedidos em '+files.length+' CSV(s); '+profiles.length+' perfil(is), '+stocks.length+' saldo(s); '+byCode.size+' materiais lidos dos PDFs. '+(notMatched.length?'Sem correspondência para: '+notMatched.join(', ')+'. ':'')+'Clique em Salvar lote para confirmar.';
 commit.hidden=false;
 }catch(err){result.textContent='Erro: '+err.message;commit.hidden=true}finally{check.disabled=false}};
commit.onclick=async()=>{if(!pending)return;commit.disabled=true;try{
 const map=new Map(rows.map(x=>[x.id,x]));
 for(const item of pending.batch){const old=map.get(item.id)||{};map.set(item.id,{...old,...item,status:old.status||item.status,delivered:old.delivered||0})}
 for(const [code,details] of pending.details){if(!/^NE\d{4}$/.test(code))continue;if(![...map.values()].some(x=>x.code===code)){const id='PROFILE|'+code;map.set(id,{id,code,order:'',description:details.description,unit:details.unit,quantity:0,delivery:'',status:'Sem pedido',category:classify(details.description,/CAMISETA|CALCA|BOTINA|RESPIRADOR/i.test(details.description)?'epis':'other'),...details})}else for(const item of map.values())if(item.code===code)Object.assign(item,Object.fromEntries(Object.entries(details).filter(([k,v])=>v!==null&&v!==undefined&&v!=='')))}
 const previous=rows;rows=[...map.values()];const h={date:br(pending.date),count:pending.batch.length,files:pending.files,profiles:[...pending.details].length};
 history=[h,...history];try{await save()}catch(e){rows=previous;history.shift();throw e}
 pending=null;render();const output=root.querySelector('#ind-import-result');if(output)output.textContent='Lote importado com sucesso: CSVs e PDFs processados.';
 }catch(err){result.textContent='Falha ao salvar: '+err.message}finally{commit.disabled=false}};
}
root.querySelectorAll('[data-import]').forEach(upload=>upload.onchange=async e=>{try{let added=0;for(const file of e.target.files){const buf=await file.arrayBuffer();let text=new TextDecoder('utf-8',{fatal:false}).decode(buf);if(text.includes('�'))text=new TextDecoder('windows-1252').decode(buf);const group=/epi|uniform/i.test(file.name)?'epis':'other';const incoming=parseCSV(text,group),map=new Map(rows.map(x=>[x.id,x]));for(const item of incoming){map.set(item.id,{...item,...(map.get(item.id)||{}),description:item.description,quantity:item.quantity,delivery:item.delivery})}rows=[...map.values()];added+=incoming.length}await save();render();root.querySelector('[data-feedback]').textContent=added+' registros processados e salvos.'}catch(err){root.querySelector('[data-feedback]').textContent='Erro na importação: '+err.message}});
root.querySelectorAll('[data-status-id]').forEach(el=>el.onchange=async()=>{const x=rows.find(x=>x.id===el.dataset.statusId);if(!x)return;const old=x.status;x.status=el.value;try{await save();render()}catch(e){x.status=old;alert(e.message)}});
root.querySelectorAll('[data-value-id]').forEach(el=>el.onchange=async()=>{const x=rows.find(x=>x.id===el.dataset.valueId),k=el.dataset.field;if(!x)return;const old=x[k];x[k]=el.value===''?null:Math.max(0,num(el.value));try{await save();render()}catch(e){x[k]=old;alert(e.message)}});

const exportButton=root.querySelector('[data-export]');if(exportButton)exportButton.onclick=()=>{const heads=['Categoria','Código','Descrição','Pedido','Quantidade','UM','Compra','Entrega','Situação','Estoque','Segurança','Consumo','Reposição'];const data=filtered().map(x=>[x.category,x.code,x.description,x.order,x.quantity,x.unit,br(x.purchase),br(x.delivery),status(x),x.stock??'',x.safety??'',x.consumption??'',x.lead??'']);const csv='\uFEFF'+[heads,...data].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='materiais-indiretos.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
}
