if(indirectToggle)indirectToggle.addEventListener('click',e=>{e.preventDefault();const children=document.querySelector('#nav-indirect-children');const closing=!children.hidden;indirectToggle.dataset.collapsed=String(closing);children.hidden=closing;indirectToggle.setAttribute('aria-expanded',String(!closing));indirectToggle.classList.toggle('indirect-active',!closing)});
document.querySelectorAll('#nav-indirect-children a').forEach(a=>a.addEventListener('click',()=>{if(indirectToggle)indirectToggle.dataset.collapsed='false'}));
syncIndirectNav();load();window.addEventListener('hashchange',()=>{syncIndirectNav();if(Object.hasOwn(routeTabs,location.hash.slice(1)))load()});
